<?php
authorizeAdmin($u);
$people=rows('SELECT * FROM users WHERE active=1 ORDER BY name');
$departments=rows('SELECT * FROM departments ORDER BY name');
$history=rows('SELECT a.*,u.name principal,v.name alternate,d.name department,c.name creator FROM designations a JOIN users u ON u.id=a.user_id LEFT JOIN users v ON v.id=a.alternate_id LEFT JOIN departments d ON d.id=a.department_id JOIN users c ON c.id=a.created_by ORDER BY a.start_date DESC,a.id DESC');
?>
<p class="page-intro">Designa jefes por dependencia y al subsecretario por fecha de inicio. El periodo anterior termina el día calendario previo. Cada trámite pendiente conserva al responsable que recibió su radicación; la nueva designación aplica a los nuevos envíos y reenvíos.</p>
<div class="detail-columns">
<?php foreach(['manager'=>'Jefe inmediato por dependencias','subsecretary'=>'Subsecretario administrativo del talento humano'] as $role=>$label): ?>
<section class="panel form-panel"><h2><?=e($label)?></h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="designation"><input type="hidden" name="role" value="<?=$role?>">
<?php foreach(['user_id'=>'Responsable principal','alternate_id'=>'Suplente para solicitudes propias'] as $key=>$text): ?><label><?=e($text)?><select name="<?=$key?>" <?=$key==='user_id'?'required':''?>><option value=""><?=$key==='user_id'?'Seleccione':'Sin suplente'?></option><?php foreach($people as $person): if(!hasRole($person,$role))continue; ?><option value="<?=(int)$person['id']?>"><?=e($person['name'])?></option><?php endforeach; ?></select></label><?php endforeach; ?>
<label>Fecha de inicio<input type="date" name="start_date" min="<?=date('Y-m-d')?>" required value="<?=date('Y-m-d')?>"></label>
<?php if($role==='manager'): ?><fieldset><legend>Dependencias a cargo</legend><div class="checks"><?php foreach($departments as $department): ?><label><input type="checkbox" name="department_ids[]" value="<?=(int)$department['id']?>"> <?=e($department['name'])?></label><?php endforeach; ?></div></fieldset><?php endif; ?>
<button class="button">Registrar designación</button></form></section>
<?php endforeach; ?></div>
<section class="panel"><div class="panel-header"><h2>Historial de designaciones</h2></div><div class="table-wrap"><table><thead><tr><th>Responsabilidad</th><th>Principal / suplente</th><th>Vigencia</th><th>Registrado por</th></tr></thead><tbody><?php foreach($history as $item): ?><tr><td><?=e(roleLabel($item['role']))?><small><?=e($item['department']??'Institucional')?></small></td><td><?=e($item['principal'])?><small>Suplente: <?=e($item['alternate']??'Sin asignar')?></small></td><td><?=e($item['start_date'])?> a <?=e($item['end_date']??'Sin fecha de cierre')?><small><?=$item['start_date']>date('Y-m-d')?'Programada':($item['end_date'] && $item['end_date']<date('Y-m-d')?'Finalizada':'Vigente')?></small></td><td><?=e($item['creator'])?><small><?=e($item['created_at'])?></small></td></tr><?php endforeach; if(!$history): ?><tr><td colspan="4">Registra las primeras designaciones para centralizar la asignación.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel form-panel"><h2>Dependencias pendientes de centralizar</h2><p class="fine">Hasta el inicio de su primera designación se conserva la configuración individual anterior. Las cuentas nuevas necesitan una designación vigente de su dependencia. No se han inventado periodos históricos ni responsables a partir del listado anterior.</p><ul><?php foreach($departments as $department): if(designation('manager',(int)$department['id']))continue; ?><li><?=e($department['name'])?></li><?php endforeach; ?></ul><p class="fine">No retires el rol de un responsable con trámites pendientes. La aplicación conserva sus aprobaciones y le permite terminar esos trámites después de finalizar su designación.</p></section>
